def numUniqueEmails(emails):
    unique_emails = set()
    for email in emails:
        local, domain = email.split('@')
        cleaned_local = []
        for c in local:
            if c == '+':
                break  # Ignore rest after '+'
            if c == '.':
                continue  # Ignore '.'
            cleaned_local.append(c)
        normalized = ''.join(cleaned_local) + '@' + domain
        unique_emails.add(normalized)
    return len(unique_emails)
